1	import React, { useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { ZimmTextInput } from 'app/components/ui-kits/atoms/zimmTextInput';
4	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
5	import { useUiCopy } from 'app/hooks/useUiCopy';
6	
7	const ZIMM_AUTH_DRAWER_CONTENT_RECIPE = 'ZimmAuthDrawerContent';
8	
9	const VALIDATION_EMPTY = 'Please enter a value.';
10	const VALIDATION_EMAIL = 'Please enter a valid email address.';
11	// Matches HTML5 type="email" validity behaviour for the common case.
12	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
13	
14	type ApiResult = { success: boolean; error?: string };
15	
16	type EmailFormProps = {
17	  emailValue: string;
18	  onEmailChange: (val: string) => void;
19	  /** May return an ApiResult — if success is false and error is set, the error is shown in the input. */
20	  onSubmit: () => Promise<ApiResult | void> | void;
21	  isLoading?: boolean;
22	  /** Forwarded to the email input for programmatic focus (e.g. drawer initialFocusRef). */
23	  inputRef?: React.RefObject<HTMLInputElement>;
24	};
25	
26	export const EmailForm = ({ emailValue, onEmailChange, onSubmit, isLoading = false, inputRef }: EmailFormProps) => {
27	  const { t } = useUiCopy();
28	  const emailLabel = t('login.drawer.email', 'Email');
29	  const sendCode = t('login.drawer.sendCode', 'Send code');
30	  const styles = useMultiStyleConfig(ZIMM_AUTH_DRAWER_CONTENT_RECIPE, {});
31	  const [validationError, setValidationError] = useState<string | undefined>();
32	
33	  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
34	    e.preventDefault();
35	    const trimmed = emailValue.trim();
36	    if (!trimmed) {
37	      setValidationError(VALIDATION_EMPTY);
38	      return;
39	    }
40	    if (!EMAIL_RE.test(trimmed)) {
41	      setValidationError(VALIDATION_EMAIL);
42	      return;
43	    }
44	    setValidationError(undefined);
45	    const result = await onSubmit();
46	    if (result && !result.success && result.error) {
47	      setValidationError(result.error);
48	    }
49	  };
50	
51	  return (
52	    <chakra.form __css={styles.emailFormStack} onSubmit={handleSubmit} noValidate>
53	      <ZimmTextInput
54	        ref={inputRef}
55	        label={emailLabel}
56	        type="email"
57	        name="email"
58	        value={emailValue}
59	        onChange={(val) => {
60	          setValidationError(undefined);
61	          onEmailChange(val);
62	        }}
63	        errorText={validationError}
64	        outlined
65	      />
66	      <ZimmButton
67	        variant="primary"
68	        size="adaptive"
69	        label={sendCode}
70	        fullWidth
71	        type="submit"
72	        disabled={isLoading}
73	      />
74	    </chakra.form>
75	  );
76	};
