1	import React from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
4	import { useUiCopy } from 'app/hooks/useUiCopy';
5	
6	const ZIMM_AUTH_DRAWER_CONTENT_RECIPE = 'ZimmAuthDrawerContent';
7	
8	const JOIN_BENEFIT_COPY = 'Join for exclusive offers, early access and a more personal experience.';
9	
10	type CreateAccountProps = {
11	  onCreateAccount: () => void;
12	};
13	
14	export const CreateAccount = ({ onCreateAccount }: CreateAccountProps) => {
15	  const { t } = useUiCopy();
16	  const heading = t('login.drawer.createAccount.heading', 'New to Zimmermann?');
17	  const joinBody = t('login.drawer.createAccount.body', JOIN_BENEFIT_COPY);
18	  const createCta = t('login.drawer.createAccount.cta', 'Create an account');
19	  const styles = useMultiStyleConfig(ZIMM_AUTH_DRAWER_CONTENT_RECIPE, {});
20	
21	  return (
22	    <chakra.div __css={styles.signupStack}>
23	      <chakra.p __css={styles.signupHeading}>{heading}</chakra.p>
24	      <chakra.p __css={styles.signupBody}>{joinBody}</chakra.p>
25	      <ZimmButton
26	        variant="secondary"
27	        size="adaptive"
28	        label={createCta}
29	        fullWidth
30	        type="button"
31	        onClick={onCreateAccount}
32	      />
33	    </chakra.div>
34	  );
35	};
