1	import React from 'react';
2	import OtpAuth from '@salesforce/retail-react-app/app/components/otp-auth';
3	import { AuthModal } from '@salesforce/retail-react-app/app/hooks/use-auth-modal';
4	import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
5	import { ZimmAuthDrawerContent } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent';
6	import { ErrorFallback } from 'app/components/ui-kits/organisms/zimmAuthDrawerContent/errorFallback';
7	import { useWishlistAuthDrawer } from 'app/hooks/useWishlistAuthDrawer';
8	
9	export type ZimmWishlistAuthDrawerProps = {
10	  /**
11	   * Called after successful passwordless/OTP login. Not invoked for IDP (Apple/Google)
12	   * flows — those trigger a full browser redirect; the user lands back already logged in.
13	   */
14	  onAuthSuccess?: () => void;
15	  /** The single trigger element (button, icon-button, etc.). Its onClick is replaced by the
16	   *  auth-gate handler — call the original action via onAuthSuccess instead. */
17	  children: React.ReactElement;
18	};
19	
20	/**
